  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Can a divergent series have a finite partial sum?', 'Yes, every partial sum is finite, but the sum to infinity doesn''t exist.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Find Σ (r + 1)² from r = 1 to n.', 'Σr² + 2Σr + n = n(n + 1)(2n + 1)/6 + n(n + 1) + n.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is Σ from r = 1 to n of r(r + 1)(r + 2)?', 'n(n + 1)(n + 2)(n + 3)/4.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Show that Σ from 1 to n of (r³ − r) = n(n + 1)(n − 1)(n + 2)/4.', 'n²(n + 1)²/4 − n(n + 1)/2 = n(n + 1)/4 × (n(n + 1) − 2) = n(n + 1)(n − 1)(n + 2)/4.', 25),
