  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you rotate y = x² about the y-axis between y = 0 and y = 4?', 'x² = y, so V = π ∫₀⁴ y dy = 8π.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the volume of a sphere derived by rotation?', 'Rotate x² + y² = r² about the x-axis: π ∫₋ᵣʳ (r² − x²) dx = (4/3)πr³.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the volume of a cone derived by rotation?', 'Rotate y = (r/h)x from 0 to h: π ∫ (r²/h²)x² dx = (1/3)πr²h.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How can volumes of revolution model real objects?', 'E.g. vases, bottles and bowls can be modelled by rotating curves.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What assumption is made when modelling an object with a volume of revolution?', 'The object is perfectly symmetrical about its axis and the curve accurately describes its profile.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = eˣ from 0 to 1 is rotated about the x-axis.', 'π ∫₀¹ e^(2x) dx = (π/2)(e² − 1).', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = 1/x from 1 to 2 is rotated about the x-axis.', 'π ∫₁² x⁻² dx = π/2.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What must you do before rotating about the y-axis?', 'Rearrange to make x² the subject in terms of y, and use y-limits.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = sin x from 0 to π is rotated about the x-axis.', 'π ∫₀^π sin²x dx = π²/2.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you find the volume of a solid with a hole?', 'Subtract the volume of the hole (inner solid) from the outer solid.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What are the units of a volume of revolution?', 'Cubic units.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the volume of a cylinder by rotation?', 'Rotate y = r from 0 to h about the x-axis: π ∫₀ʰ r² dx = πr²h.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you find the limits for the region between y = x and y = x²?', 'Solve x = x²: x = 0 and x = 1.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when the region between y = x and y = x² is rotated about the x-axis.', 'π ∫₀¹ (x² − x⁴) dx = π(1/3 − 1/5) = 2π/15.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What if the curve crosses the axis of rotation?', 'y² is always positive, so the volume formula still works, but check the region carefully.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How can a volume of revolution be scaled to model a real object?', 'Multiply by the cube of the scale factor, or use scaled units.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Why might a model underestimate a real vase''s volume?', 'The curve may not match the real shape exactly, or the wall thickness may be ignored.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What volume is generated by rotating y = 2 between x = 1 and x = 3?', 'A cylinder: π × 4 × 2 = 8π.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = x³ from 0 to 1 is rotated about the y-axis.', 'x = y^(1/3), x² = y^(2/3): π ∫₀¹ y^(2/3) dy = 3π/5.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the washer method?', 'Finding the volume of a solid with a hole by subtracting inner from outer volumes.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you find the volume of a region bounded by a curve and a line not on an axis?', 'Find the intersection points, then subtract the volume under the line from the volume under the curve.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Which integral gives volume about the x-axis for y = f(x)?', 'π ∫ [f(x)]² dx.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Why is volume of revolution an application of integration?', 'The solid is split into thin discs of volume πy² δx, which are summed as δx → 0.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the order of a matrix?', 'The number of rows × the number of columns.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'When can two matrices be multiplied?', 'When the number of columns in the first equals the number of rows in the second.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Is matrix multiplication commutative?', 'No; in general AB ≠ BA.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Is matrix multiplication associative?', 'Yes: (AB)C = A(BC).', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the identity matrix I?', 'A square matrix with 1s on the leading diagonal and 0s elsewhere; AI = IA = A.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the determinant of a 2×2 matrix (a b; c d)?', 'ad − bc.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the inverse of a 2×2 matrix (a b; c d)?', '(1/(ad − bc)) × (d −b; −c a).', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is a singular matrix?', 'A matrix with determinant zero, which has no inverse.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is (AB)⁻¹?', 'B⁻¹A⁻¹.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How do you find the determinant of a 3×3 matrix?', 'Expand along a row or column using cofactors: a(ei − fh) − b(di − fg) + c(dh − eg).', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What does the determinant of a transformation matrix represent?', 'The area (2D) or volume (3D) scale factor; a negative value means orientation is reversed.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How can matrices solve simultaneous equations?', 'Write as AX = B, then X = A⁻¹B if A is non-singular.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What does det A = 0 mean for a system of 3 equations?', 'There is no unique solution: either no solutions (inconsistent) or infinitely many.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How do three planes with no unique solution appear geometrically?', 'As a sheaf (common line), a prism (no common point), or with parallel planes.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is det(AB)?', 'det A × det B.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the transpose of a matrix?', 'The matrix formed by swapping rows and columns, Aᵀ.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How do you find the inverse of a 3×3 matrix?', 'Find the matrix of cofactors, transpose it (adjugate), then divide by the determinant.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the zero matrix?', 'A matrix in which every element is 0.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Multiply (1 2; 3 4)(0 1; 1 0).', '(2 1; 4 3).', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Find the determinant of (3 1; 5 2).', '6 − 5 = 1.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Find the inverse of (3 1; 5 2).', '(2 −1; −5 3).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'For what value of k is (k 2; 3 6) singular?', '6k − 6 = 0, so k = 1.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is A² for a matrix A?', 'A × A (only defined for square matrices).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What does it mean if AB = I?', 'B is the inverse of A (and A is the inverse of B).', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How is a system of linear equations consistent?', 'When it has at least one solution.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is a minor in a 3×3 determinant?', 'The determinant of the 2×2 matrix left after deleting a row and column.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is a cofactor?', 'A minor multiplied by (−1)^(i+j).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'If det A = 3, what is det(2A) for a 3×3 matrix?', '2³ × 3 = 24.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'If det A = 5, what is det(A⁻¹)?', '1/5.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How do you check a matrix inverse is correct?', 'Multiply by the original matrix and check the result is I.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What transformation does (1 0; 0 −1) represent?', 'A reflection in the x-axis.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What transformation does (−1 0; 0 1) represent?', 'A reflection in the y-axis.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What transformation does (0 1; 1 0) represent?', 'A reflection in the line y = x.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents an anticlockwise rotation by θ about the origin?', '(cos θ −sin θ; sin θ cos θ).', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents an enlargement by scale factor k about the origin?', '(k 0; 0 k).', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a stretch parallel to the x-axis, scale factor k?', '(k 0; 0 1).', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does the matrix (1 k; 0 1) represent?', 'A shear with the x-axis invariant: each point moves parallel to the x-axis by k times its y-coordinate.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you find the image of a point under a transformation?', 'Multiply the transformation matrix by the position vector of the point.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you find the matrix of a transformation?', 'Find the images of the unit vectors i and j (and k); these form the columns.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is the matrix for a combined transformation "A then B"?', 'BA (the first transformation is on the right).', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is an invariant point?', 'A point that maps to itself under a transformation.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is an invariant line?', 'A line where every point on it maps to a point on the same line.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is a line of invariant points?', 'A line where every point maps to itself.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you find invariant points of a matrix M?', 'Solve M(x, y) = (x, y).', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you find invariant lines y = mx + c?', 'Map a general point (x, mx + c) and require the image to satisfy the same equation, for all x.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is the area of an image under transformation M?', '|det M| × original area.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does a negative determinant tell you about a transformation?', 'It reverses orientation (includes a reflection).', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a reflection in y = −x?', '(0 −1; −1 0).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a rotation of 90° anticlockwise about the origin?', '(0 −1; 1 0).', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a rotation of 180° about the origin?', '(−1 0; 0 −1).', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a rotation about the z-axis in 3D?', '(cos θ −sin θ 0; sin θ cos θ 0; 0 0 1).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a reflection in the plane z = 0?', '(1 0 0; 0 1 0; 0 0 −1).', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you reverse a transformation?', 'Apply the inverse matrix.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'Why is a singular matrix transformation not reversible?', 'It collapses the plane onto a line or point, so information is lost.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does a rotation matrix''s determinant equal?', '1.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does a reflection matrix''s determinant equal?', '−1.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'Find the image of (2, 3) under (1 2; 0 1).', '(2 + 6, 3) = (8, 3).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does (2 0; 0 3) do to a unit square''s area?', 'It multiplies it by 6.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is the matrix for a rotation of θ clockwise?', '(cos θ sin θ; −sin θ cos θ).', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is a shear''s effect on area?', 'None: a shear has determinant 1.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What are the steps of proof by induction?', 'Basis (show true for n = 1), assumption (assume true for n = k), inductive step (show true for n = k + 1), conclusion.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What should the conclusion of an induction proof state?', 'If true for n = k, it is true for n = k + 1; since it is true for n = 1, it is true for all positive integers n.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove Σ r from 1 to n = n(n + 1)/2 by induction: what is the inductive step?', 'Assume Σ to k = k(k + 1)/2. Then Σ to k + 1 = k(k + 1)/2 + (k + 1) = (k + 1)(k + 2)/2.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for divisibility?', 'Show f(1) is divisible by m, then write f(k + 1) in terms of f(k) plus a multiple of m.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove 6ⁿ − 1 is divisible by 5 for n ≥ 1.', 'n = 1: 5. Assume 6ᵏ − 1 = 5m. Then 6^(k+1) − 1 = 6(6ᵏ − 1) + 5 = 30m + 5, divisible by 5.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove 3^(2n) − 1 is divisible by 8.', 'n = 1: 8. Assume 9ᵏ − 1 = 8m. Then 9^(k+1) − 1 = 9(9ᵏ − 1) + 8 = 72m + 8.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for matrices?', 'Show the formula for Mⁿ holds for n = 1, then multiply Mᵏ by M to get the formula for M^(k+1).', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove by induction that (1 1; 0 1)ⁿ = (1 n; 0 1).', 'n = 1 is true. Assume true for k; then (1 k; 0 1)(1 1; 0 1) = (1 k + 1; 0 1).', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for recurrence relations?', 'Show the closed form matches u₁, then use the recurrence with the assumption to show it holds for u_(k+1).', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove uₙ = 2ⁿ − 1 if u₁ = 1, u_(n+1) = 2uₙ + 1.', 'n = 1: 1. Assume u_k = 2ᵏ − 1. Then u_(k+1) = 2(2ᵏ − 1) + 1 = 2^(k+1) − 1.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for derivatives?', 'Show the formula for the n-th derivative holds for n = 1, then differentiate the k-th to get the (k + 1)-th.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove that d^n/dx^n (x eˣ) = (x + n)eˣ.', 'n = 1: (x + 1)eˣ. Assume true for k; differentiating (x + k)eˣ gives (x + k + 1)eˣ.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Why is the basis step necessary?', 'Without it, the chain of implications has no starting point.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Why is the inductive step alone not enough?', 'It only shows "if true for k then true for k + 1", not that it is ever true.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Can induction start from a value other than 1?', 'Yes; the basis can be any integer, and the result holds for all integers from there.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What is a common error in induction proofs?', 'Assuming the result for k + 1 instead of deriving it, or omitting the conclusion.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove Σ r² = n(n + 1)(2n + 1)/6: what must be shown in the inductive step?', 'k(k + 1)(2k + 1)/6 + (k + 1)² = (k + 1)(k + 2)(2k + 3)/6.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove that 2ⁿ > n for all n ≥ 1.', 'n = 1: 2 > 1. Assume 2ᵏ > k. Then 2^(k+1) = 2 × 2ᵏ > 2k ≥ k + 1 for k ≥ 1.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for inequalities?', 'Use the assumption and then show the next case satisfies the inequality, often using extra algebraic steps.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove n³ − n is divisible by 6 using induction.', 'n = 1: 0. (k + 1)³ − (k + 1) = (k³ − k) + 3k(k + 1); k(k + 1) is even, so 3k(k + 1) is a multiple of 6.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What is the key idea of induction?', 'Like dominoes: if the first falls and each one knocks over the next, all fall.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What is proof by exhaustion compared with induction?', 'Exhaustion checks a finite number of cases; induction proves infinitely many.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Can induction prove statements about all real numbers?', 'No, only about integers (or well-ordered sets).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove 7ⁿ − 3ⁿ is divisible by 4.', 'n = 1: 4. 7^(k+1) − 3^(k+1) = 7(7ᵏ − 3ᵏ) + 4 × 3ᵏ, divisible by 4.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What should you write for the assumption step?', '"Assume the statement is true for n = k", then write out the statement with k.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How do you prove a sum formula for Σ r(r + 1)?', 'Basis with n = 1, assume for k, add (k + 1)(k + 2), and factorise.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Why must the final result be clearly shown to match the formula with k + 1?', 'To demonstrate that the statement holds for n = k + 1.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What does "for all n ∈ ℤ⁺" mean?', 'For all positive integers n.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove that 4ⁿ + 6n − 1 is divisible by 9.', 'n = 1: 9. f(k + 1) − 4f(k) = 6(k + 1) − 1 − 24k + 4 = −18k + 9, a multiple of 9.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Why might f(k + 1) − f(k) be useful in divisibility proofs?', 'If it is divisible by m and f(k) is, then so is f(k + 1).', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the vector equation of a line?', 'r = a + λb, where a is a point on the line and b is the direction vector.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the Cartesian equation of a line?', '(x − a₁)/b₁ = (y − a₂)/b₂ = (z − a₃)/b₃.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the scalar (dot) product?', 'a·b = a₁b₁ + a₂b₂ + a₃b₃ = |a||b| cos θ.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What does a·b = 0 mean?', 'The vectors are perpendicular.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the angle between two lines?', 'Use the dot product of their direction vectors: cos θ = (b₁·b₂)/(|b₁||b₂|).', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the vector equation of a plane?', 'r = a + λb + μc, or r·n = a·n.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the Cartesian equation of a plane?', 'n₁x + n₂y + n₃z = d, where n is the normal.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is a normal vector to a plane?', 'A vector perpendicular to the plane.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the angle between a line and a plane?', 'Find the angle between the direction and the normal, then subtract from 90°.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the angle between two planes?', 'Find the angle between their normals.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find where a line meets a plane?', 'Substitute the line''s parametric form into the plane equation and solve for λ.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you tell if two lines are skew?', 'They are not parallel and don''t intersect.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the intersection of two lines?', 'Set the vector equations equal and solve for the parameters, checking all three components.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the vector (cross) product?', 'a × b, a vector perpendicular to both a and b with magnitude |a||b| sin θ.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you calculate a × b?', '(a₂b₃ − a₃b₂, a₃b₁ − a₁b₃, a₁b₂ − a₂b₁).', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the normal to a plane containing vectors b and c?', 'Calculate b × c.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the perpendicular distance from a point to a plane?', '|ax₀ + by₀ + cz₀ − d|/√(a² + b² + c²).', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the shortest distance between skew lines?', '|(a₂ − a₁)·n|/|n|, where n = b₁ × b₂.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the shortest distance from a point to a line?', 'Find the foot of the perpendicular (where (p − r)·b = 0), then find the distance.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the area of a triangle using vectors?', '½|AB × AC|.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the volume of a parallelepiped?', '|a·(b × c)| (the scalar triple product).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the line of intersection of two planes?', 'It has direction n₁ × n₂; find a point by solving the equations with one variable fixed.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the reflection of a point in a plane?', 'Find the foot of the perpendicular, then go the same distance beyond it.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'When are two planes parallel?', 'When their normals are parallel.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What does r·n = d mean geometrically?', 'All points whose component along n is d/|n| from the origin.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'Find the angle between (1, 2, 2) and (2, −1, 2).', 'Dot product = 2 − 2 + 4 = 4; |a| = |b| = 3; cos θ = 4/9, θ ≈ 63.6°.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you check a point lies on a line?', 'Find a λ that satisfies all three components.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is a unit normal?', 'A normal vector divided by its magnitude.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'Find the Cartesian equation of the plane with normal (2, −1, 3) through (1, 1, 1).', '2x − y + 3z = 4.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the scalar product of a vector with itself?', 'a·a = |a|².', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is Euler''s formula?', 'e^(iθ) = cos θ + i sin θ.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the exponential form of a complex number?', 'z = re^(iθ).', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is e^(iπ)?', '−1.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'State de Moivre''s theorem.', '[r(cos θ + i sin θ)]ⁿ = rⁿ(cos nθ + i sin nθ).', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Calculate (1 + i)⁸ using de Moivre.', '(√2)⁸(cos 2π + i sin 2π) = 16.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How can de Moivre express cos 3θ in terms of cos θ?', 'Expand (cos θ + i sin θ)³ and take the real part: cos 3θ = 4cos³θ − 3cos θ.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Express sin 3θ in terms of sin θ.', 'sin 3θ = 3 sin θ − 4 sin³θ.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is z + 1/z if z = e^(iθ)?', '2 cos θ.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is z − 1/z if z = e^(iθ)?', '2i sin θ.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is zⁿ + 1/zⁿ if z = e^(iθ)?', '2 cos nθ.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How do you express cos⁴θ in terms of multiple angles?', 'Expand (z + 1/z)⁴ = 16cos⁴θ, giving cos⁴θ = (cos 4θ + 4cos 2θ + 3)/8.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What are the n-th roots of unity?', 'The solutions of zⁿ = 1: z = e^(2πki/n) for k = 0, 1, …, n − 1.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the sum of the n-th roots of unity (n > 1)?', '0.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Find the cube roots of unity.', '1, e^(2πi/3), e^(4πi/3), i.e. 1 and −½ ± (√3/2)i.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'If ω is a primitive cube root of unity, what is 1 + ω + ω²?', '0.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Solve z³ = 8i.', '8i = 8e^(iπ/2), so z = 2e^(i(π/6 + 2πk/3)), k = 0, 1, 2: 2e^(iπ/6), 2e^(i5π/6), 2e^(−iπ/2).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How do you solve zⁿ = w in general?', 'Write w = re^(iθ); then z = r^(1/n) e^(i(θ + 2πk)/n), k = 0, …, n − 1.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How are the n-th roots of a complex number arranged?', 'Equally spaced around a circle of radius r^(1/n), separated by 2π/n.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How do you sum a series like Σ cos kθ using complex numbers?', 'Sum the geometric series Σ e^(ikθ) and take the real part.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the conjugate of re^(iθ)?', 're^(−iθ).', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is e^(iθ) × e^(iφ)?', 'e^(i(θ + φ)).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Express −2 in exponential form.', '2e^(iπ).', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the modulus of e^(iθ)?', '1.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Use de Moivre to find (cos π/6 + i sin π/6)⁶.', 'cos π + i sin π = −1.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How can roots of unity solve (z + 1)⁵ = z⁵?', 'Divide: ((z + 1)/z)⁵ = 1, so (z + 1)/z = ω, the fifth roots of unity (excluding 1), and solve for z.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What does de Moivre''s theorem say for negative n?', 'It also holds: (cos θ + i sin θ)^(−n) = cos nθ − i sin nθ.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How is cos θ written in exponential form?', 'cos θ = (e^(iθ) + e^(−iθ))/2.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How is sin θ written in exponential form?', 'sin θ = (e^(iθ) − e^(−iθ))/(2i).', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the principal argument?', 'The argument θ with −π < θ ≤ π.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What geometric transformation does multiplying by e^(iπ/3) represent?', 'A rotation by π/3 anticlockwise about the origin.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is a Maclaurin series?', 'f(x) = f(0) + f''(0)x + f''''(0)x²/2! + f''''''(0)x³/3! + …', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for eˣ?', '1 + x + x²/2! + x³/3! + …, valid for all x.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for sin x?', 'x − x³/3! + x⁵/5! − …, valid for all x.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for cos x?', '1 − x²/2! + x⁴/4! − …, valid for all x.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for ln(1 + x)?', 'x − x²/2 + x³/3 − …, valid for −1 < x ≤ 1.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for (1 + x)ⁿ?', '1 + nx + n(n − 1)x²/2! + …, valid for |x| < 1 (non-integer n).', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the Maclaurin series for e^(2x) up to x³.', '1 + 2x + 2x² + (4/3)x³.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for sin 3x up to x³.', '3x − (27/6)x³ = 3x − 4.5x³.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for eˣ sin x up to x³.', '(1 + x + x²/2)(x − x³/6) = x + x² + x³/3 + …', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for ln(1 − x) up to x³.', '−x − x²/2 − x³/3.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the validity of ln(1 − x)''s series?', '−1 ≤ x < 1.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How can a Maclaurin series approximate a value?', 'Substitute a small x into the first few terms, e.g. e^0.1 ≈ 1 + 0.1 + 0.005.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How can series find limits?', 'Replace functions with their series and simplify, e.g. lim (sin x)/x = 1.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find lim (x→0) of (1 − cos x)/x².', '(x²/2 − …)/x² → 1/2.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find lim (x→0) of (eˣ − 1)/x.', '(x + x²/2 + …)/x → 1.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is a Taylor series?', 'An expansion about x = a: f(x) = f(a) + f''(a)(x − a) + f''''(a)(x − a)²/2! + …', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Why are Taylor series about x = a useful?', 'They give good approximations near x = a, where the Maclaurin series might not converge or be accurate.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the Taylor series of ln x about x = 1 up to (x − 1)².', '(x − 1) − (x − 1)²/2.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Why does ln x not have a Maclaurin series?', 'ln x and its derivatives aren''t defined at x = 0.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How do you find the series for cos²x?', 'Use cos²x = (1 + cos 2x)/2 and the series for cos 2x: 1 − x² + x⁴/3 − …', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for √(1 + x) up to x².', '1 + x/2 − x²/8.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How do you differentiate a Maclaurin series?', 'Differentiate term by term, e.g. the derivative of sin x''s series gives cos x''s series.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How can you integrate using series?', 'Integrate the series term by term, e.g. to approximate ∫ e^(−x²) dx.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the series for arctan x?', 'x − x³/3 + x⁵/5 − …, valid for |x| ≤ 1.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the general term of the eˣ series?', 'xʳ/r!.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the general term of the sin x series?', '(−1)ʳ x^(2r+1)/(2r + 1)!.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Why is only a finite number of terms used in practice?', 'Higher terms become very small for small x, so a few terms give a good approximation.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for tan x up to x³.', 'x + x³/3.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How do you find the series for e^(sin x)?', 'Substitute the series for sin x into eᵘ = 1 + u + u²/2 + … and collect terms.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for sinh x.', 'x + x³/3! + x⁵/5! + …', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is an improper integral?', 'An integral where a limit is infinite or the integrand is undefined at a point in the range.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you evaluate ∫₁^∞ 1/x² dx?', 'lim (t→∞) [−1/x]₁ᵗ = 1.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Does ∫₁^∞ 1/x dx converge?', 'No; ln t → ∞, so it diverges.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Evaluate ∫₀¹ 1/√x dx.', '[2√x]₀¹ = 2 (the integral converges even though 1/√x is undefined at 0).', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the mean value of f(x) over [a, b]?', '(1/(b − a)) ∫ₐᵇ f(x) dx.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Find the mean value of x² over [0, 3].', '(1/3) × 9 = 3.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is ∫ 1/√(1 − x²) dx?', 'arcsin x + c.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is ∫ 1/(1 + x²) dx?', 'arctan x + c.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is ∫ 1/√(a² − x²) dx?', 'arcsin(x/a) + c.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is ∫ 1/(a² + x²) dx?', '(1/a) arctan(x/a) + c.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the derivative of arcsin x?', '1/√(1 − x²).', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the derivative of arccos x?', '−1/√(1 − x²).', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the derivative of arctan x?', '1/(1 + x²).', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Integrate 1/(x² + 4).', '(1/2) arctan(x/2) + c.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Integrate 1/√(9 − x²).', 'arcsin(x/3) + c.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you integrate 1/(x² + 2x + 5)?', 'Complete the square: (x + 1)² + 4, giving (1/2) arctan((x + 1)/2) + c.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do partial fractions help integrate 1/((x + 1)(x² + 1))?', 'Split into A/(x + 1) + (Bx + C)/(x² + 1), then integrate using ln and arctan.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the partial fraction form for (px + q)/((x − a)(x² + b²))?', 'A/(x − a) + (Bx + C)/(x² + b²).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Integrate x/(x² + 1).', '½ ln(x² + 1) + c.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you integrate 1/√(x² + a²)?', 'arsinh(x/a) + c, or ln(x + √(x² + a²)) + c.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you integrate 1/√(x² − a²)?', 'arcosh(x/a) + c, or ln(x + √(x² − a²)) + c.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is a reduction formula?', 'A formula expressing an integral Iₙ in terms of Iₙ₋₁ or Iₙ₋₂, often found using integration by parts.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Derive a reduction formula for Iₙ = ∫ xⁿ eˣ dx.', 'By parts: Iₙ = xⁿeˣ − nIₙ₋₁.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the arc length of a curve y = f(x)?', 's = ∫ √(1 + (dy/dx)²) dx.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the arc length for a parametric curve?', 's = ∫ √((dx/dt)² + (dy/dt)²) dt.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the surface area of revolution about the x-axis?', 'S = 2π ∫ y √(1 + (dy/dx)²) dx.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Why might an improper integral diverge?', 'The area is infinite because the function doesn''t decrease fast enough, or has an infinite discontinuity.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you evaluate ∫₀^∞ e^(−x) dx?', 'lim (t→∞) [−e^(−x)]₀ᵗ = 1.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is lim (x→∞) x e^(−x)?', '0, because exponentials grow faster than polynomials.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What substitution integrates 1/√(1 − x²) directly?', 'x = sin θ.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you find a volume of revolution for a parametric curve about the x-axis?', 'V = π ∫ y² (dx/dt) dt, with limits in t.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you find a volume about the y-axis for a parametric curve?', 'V = π ∫ x² (dy/dt) dt.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when x = t², y = 2t for 0 ≤ t ≤ 1 is rotated about the x-axis.', 'π ∫₀¹ 4t² × 2t dt = 8π × ¼ = 2π.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when x = cos t, y = sin t (0 ≤ t ≤ π) is rotated about the x-axis.', 'A sphere of radius 1: 4π/3.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Why must limits be converted to t for parametric volumes?', 'The integral is with respect to t, so the x-limits must be replaced by corresponding t-values.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can you avoid sign errors in parametric volumes?', 'Check whether x increases or decreases with t; swap limits if needed so the volume is positive.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can volumes of revolution model a wine glass?', 'By rotating a curve describing the glass''s profile, possibly in parts.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you model a composite solid?', 'Split it into sections, find the volume of each, and add.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when y = ln x from 1 to e is rotated about the y-axis.', 'x = eʸ, x² = e^(2y): π ∫₀¹ e^(2y) dy = (π/2)(e² − 1).', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when y = cosh x from 0 to 1 is rotated about the x-axis.', 'π ∫₀¹ cosh²x dx = (π/2)(1 + sinh 2/2) = (π/4)(2 + sinh 2).', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you rotate around a line other than an axis, e.g. y = 1?', 'Use π ∫ (y − 1)² dx, measuring the radius from the line.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can a volume of revolution be used to find the mass of an object?', 'Multiply the volume by the density.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What is the volume when the region between y = 2x and y = x² is rotated about the y-axis?', 'x = y/2 and x = √y: π ∫₀⁴ (y − y²/4) dy = π(8 − 16/3) = 8π/3.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can you check a volume of revolution answer?', 'Compare with a simple shape of similar size (cone, cylinder or sphere).', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What is the limitation of using a volume of revolution to model a bottle?', 'Real bottles have thickness, necks and non-symmetrical features.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume of y = √(sin x) from 0 to π rotated about the x-axis.', 'π ∫₀^π sin x dx = 2π.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What substitution helps find π ∫ y² dx if y = 1/√(1 + x²)?', 'π ∫ 1/(1 + x²) dx = π arctan x.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when y = 1/√(1 + x²) from 0 to 1 is rotated about the x-axis.', 'π arctan 1 = π²/4.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when y = sec x from 0 to π/4 is rotated about the x-axis.', 'π ∫ sec²x dx = π tan(π/4) = π.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can volumes of revolution involve integration by parts?', 'E.g. rotating y = √x eˣ requires ∫ x e^(2x) dx, which needs integration by parts.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What is the volume of a torus (doughnut)?', '2π²Rr², where R is the distance from the centre to the tube''s centre and r is the tube''s radius.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How is the volume of a region rotated 360° different from rotating by 2π?', 'They are the same: a full turn of 360° is 2π radians.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when x = t + 1, y = t² for 0 ≤ t ≤ 1 is rotated about the x-axis.', 'π ∫₀¹ t⁴ × 1 dt = π/5.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you find the volume when rotating about the y-axis a curve given as y = f(x)?', 'Rearrange to x = g(y) and use π ∫ [g(y)]² dy.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What is the volume of a hemispherical bowl of radius r?', '(2/3)πr³.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What happens to the volume if the curve is scaled by factor k in both directions?', 'The volume scales by k³.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What happens to the volume if y is scaled by k?', 'The volume scales by k².', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How is Pappus''s theorem related to volumes of revolution?', 'Volume = area × distance travelled by the centroid (2π × distance to the axis).', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How is a volume of revolution calculated numerically when the integral is hard?', 'Use numerical methods such as the trapezium rule or Simpson''s rule on π y².', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Why might a model use two different curves for the inside and outside of a cup?', 'To account for the thickness of the cup''s walls.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What are polar coordinates?', 'Coordinates (r, θ), where r is the distance from the pole and θ is the angle from the initial line.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you convert polar to Cartesian?', 'x = r cos θ, y = r sin θ.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you convert Cartesian to polar?', 'r² = x² + y², tan θ = y/x (taking care with the quadrant).', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the polar equation r = a?', 'A circle with centre the pole and radius a.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the polar equation θ = α?', 'A half-line from the pole at angle α.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the curve r = aθ?', 'A spiral (Archimedean spiral).', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the curve r = a(1 + cos θ)?', 'A cardioid.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the curve r = a cos 2θ?', 'A four-petalled rose curve.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the curve r = 2a cos θ?', 'A circle through the pole, with centre (a, 0) and radius a.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the area enclosed by a polar curve?', 'A = ½ ∫ r² dθ between the limits.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Find the area enclosed by r = 2 for 0 ≤ θ ≤ 2π.', '½ ∫ 4 dθ = 4π.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Find the area of the cardioid r = 1 + cos θ.', '½ ∫₀^(2π) (1 + cos θ)² dθ = 3π/2.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you find where two polar curves intersect?', 'Set the r-values equal and solve for θ, also checking the pole.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you find a tangent parallel to the initial line?', 'Set dy/dθ = 0, where y = r sin θ.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you find a tangent perpendicular to the initial line?', 'Set dx/dθ = 0, where x = r cos θ.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Convert r = 4 sin θ to Cartesian form.', 'r² = 4r sin θ, so x² + y² = 4y (a circle centred at (0, 2)).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Convert x² + y² = 9 to polar form.', 'r = 3.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Convert y = x to polar form.', 'θ = π/4 (and θ = −3π/4 for negative r).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Why is r usually taken as non-negative?', 'By convention r ≥ 0; values of θ that give negative r are excluded from the sketch.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What does a cardioid look like?', 'A heart shape with a cusp at the pole.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How many petals does r = cos 3θ have?', '3.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How many petals does r = cos 2θ have?', '4.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the area of one petal of r = cos 2θ?', '½ ∫ from −π/4 to π/4 of cos²2θ dθ = π/8.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What identity helps integrate r² = cos²θ?', 'cos²θ = (1 + cos 2θ)/2.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you sketch a polar curve?', 'Tabulate r for key θ values, note symmetry, and find where r = 0 and r is maximum.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What does symmetry about the initial line mean for r = f(θ)?', 'f(−θ) = f(θ), e.g. curves involving only cos θ.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you find the area between two polar curves?', 'Subtract the areas: ½ ∫ (r₁² − r₂²) dθ over the appropriate range.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the maximum r of r = 3 + 2 cos θ?', '5, when θ = 0.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Does r = 3 + 2 cos θ pass through the pole?', 'No, since r ≥ 1 for all θ (a dimpled limaçon).', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the pole?', 'The origin in polar coordinates.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the definition of sinh x?', 'sinh x = (eˣ − e^(−x))/2.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the definition of cosh x?', 'cosh x = (eˣ + e^(−x))/2.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the definition of tanh x?', 'tanh x = sinh x/cosh x = (eˣ − e^(−x))/(eˣ + e^(−x)).', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the key hyperbolic identity?', 'cosh²x − sinh²x = 1.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the range of cosh x?', 'cosh x ≥ 1.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the range of tanh x?', '−1 < tanh x < 1.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What does the graph of y = cosh x look like?', 'A U-shape (catenary) with minimum (0, 1), symmetric about the y-axis.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What does the graph of y = sinh x look like?', 'An S-shape through the origin, increasing, and odd.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of sinh x?', 'cosh x.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of cosh x?', 'sinh x.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of tanh x?', 'sech²x.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is Osborn''s rule?', 'To convert a trig identity to a hyperbolic one, replace cos with cosh and sin with sinh, but change the sign of any product of two sines.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is sinh 2x?', '2 sinh x cosh x.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is cosh 2x?', 'cosh²x + sinh²x = 2cosh²x − 1 = 1 + 2sinh²x.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is arsinh x in logarithmic form?', 'ln(x + √(x² + 1)).', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is arcosh x in logarithmic form?', 'ln(x + √(x² − 1)), for x ≥ 1.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is artanh x in logarithmic form?', '½ ln((1 + x)/(1 − x)), for |x| < 1.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of arsinh x?', '1/√(x² + 1).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of arcosh x?', '1/√(x² − 1).', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of artanh x?', '1/(1 − x²).', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Solve cosh x = 2.', 'x = ±ln(2 + √3).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Solve sinh x = 3/4.', 'x = ln(3/4 + 5/4) = ln 2.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Solve 3 sinh x + cosh x = 3.', 'In exponentials: 3(eˣ − e^(−x))/2 + (eˣ + e^(−x))/2 = 3 → 2eˣ − e^(−x) = 3 → 2e^(2x) − 3eˣ − 1 = 0, eˣ = (3 + √17)/4, x = ln((3 + √17)/4).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is ∫ sinh x dx?', 'cosh x + c.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is ∫ cosh x dx?', 'sinh x + c.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is ∫ tanh x dx?', 'ln cosh x + c.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is a catenary?', 'The shape of a hanging chain, described by y = a cosh(x/a).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Is cosh x even or odd?', 'Even.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Is sinh x even or odd?', 'Odd.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is sech x?', '1/cosh x.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is an integrating factor?', 'For dy/dx + P(x)y = Q(x), the integrating factor is e^(∫P dx).', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'How do you solve dy/dx + P(x)y = Q(x)?', 'Multiply by the integrating factor I: d(Iy)/dx = IQ, then integrate.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve dy/dx + 2y = e^(−x).', 'IF = e^(2x): (ye^(2x))'' = eˣ, so y = e^(−x) + Ce^(−2x).', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve x dy/dx + y = x².', '(xy)'' = x², so xy = x³/3 + C, y = x²/3 + C/x.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is a second-order linear differential equation with constant coefficients?', 'a d²y/dx² + b dy/dx + cy = f(x).', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the auxiliary equation?', 'am² + bm + c = 0.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the complementary function if the auxiliary equation has distinct real roots α, β?', 'y = Ae^(αx) + Be^(βx).', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the complementary function for a repeated root α?', 'y = (A + Bx)e^(αx).', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the complementary function for complex roots p ± qi?', 'y = e^(px)(A cos qx + B sin qx).', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the general solution of a non-homogeneous second-order ODE?', 'Complementary function + particular integral.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is a particular integral?', 'Any solution of the full equation, found by trying a function similar to f(x).', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What trial function is used for f(x) = ke^(λx)?', 'Ae^(λx) (or Axe^(λx) if λ is a root of the auxiliary equation).', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What trial function is used for f(x) = polynomial of degree n?', 'A general polynomial of degree n.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What trial function is used for f(x) = k cos ωx?', 'A cos ωx + B sin ωx.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What happens if the trial function is part of the complementary function?', 'Multiply the trial by x (or x² for a repeated root).', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y'''' − 5y'' + 6y = 0.', 'm² − 5m + 6 = 0, m = 2, 3: y = Ae^(2x) + Be^(3x).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y'''' + 4y = 0.', 'm = ±2i: y = A cos 2x + B sin 2x.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y'''' + 2y'' + y = 0.', 'm = −1 (repeated): y = (A + Bx)e^(−x).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Find a particular integral for y'''' − y = 2x.', 'Try y = ax + b: −ax − b = 2x, so y = −2x.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'How are boundary conditions used?', 'They determine the constants A and B, giving a particular solution.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is a homogeneous equation?', 'One where f(x) = 0.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'How do you solve simultaneous first-order DEs such as dx/dt = ax + by, dy/dt = cx + dy?', 'Differentiate one equation and substitute to get a second-order equation in one variable.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What does separating variables require?', 'The equation can be written as g(y) dy = f(x) dx.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve dy/dx = y tan x.', 'ln|y| = −ln|cos x| + c, so y = A sec x.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y'''' − 4y'' + 13y = 0.', 'm = 2 ± 3i: y = e^(2x)(A cos 3x + B sin 3x).', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What trial is used for y'''' + y = sin x?', 'Since sin x is in the CF, try x(A cos x + B sin x).', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What substitution can reduce a DE to separable form?', 'E.g. y = vx for homogeneous equations dy/dx = f(y/x).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the order of a differential equation?', 'The highest derivative that appears.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'How do you check a DE solution?', 'Differentiate and substitute back into the equation.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is a first-order linear DE?', 'One of the form dy/dx + P(x)y = Q(x).', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is simple harmonic motion as a differential equation?', 'd²x/dt² = −ω²x.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the general solution of d²x/dt² = −ω²x?', 'x = A cos ωt + B sin ωt.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is damped harmonic motion?', 'd²x/dt² + k dx/dt + ω²x = 0, where the damping term reduces the amplitude.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is heavy damping?', 'The auxiliary equation has two distinct real (negative) roots; the system returns to equilibrium slowly without oscillating.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is critical damping?', 'The auxiliary equation has a repeated root; the system returns to equilibrium fastest without oscillating.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is light damping?', 'The auxiliary equation has complex roots; the system oscillates with decreasing amplitude.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is forced oscillation?', 'An oscillating system with an external driving force: x'''' + kx'' + ω²x = f(t).', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is resonance in DEs?', 'When the driving frequency equals the natural frequency, amplitude grows (the particular integral includes t).', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is population growth with limits modelled?', 'dP/dt = kP(1 − P/K), the logistic equation.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is predator–prey interaction modelled?', 'Using coupled first-order differential equations for each population.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the general strategy for coupled DEs?', 'Eliminate one variable by differentiating to give a second-order DE in the other.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What does the steady state of a model mean?', 'The long-term behaviour, e.g. when derivatives are zero.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the model for Newton''s law of cooling?', 'dT/dt = −k(T − T_s).', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is a mixing problem modelled?', 'Rate of change of amount = rate in − rate out, where rate out depends on the concentration.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'Set up a DE: a tank contains 100 L of water with 10 kg salt; brine at 0.5 kg/L enters at 2 L/min and mixture leaves at 2 L/min.', 'dS/dt = 1 − 2S/100 = 1 − S/50.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the solution of dS/dt = 1 − S/50 with S(0) = 10?', 'S = 50 − 40e^(−t/50).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is air resistance included in a motion model?', 'Add a resistive term such as −kv or −kv² to the force equation.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'Solve m dv/dt = mg − kv for v with v(0) = 0.', 'v = (mg/k)(1 − e^(−kt/m)).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the terminal velocity in m dv/dt = mg − kv?', 'mg/k.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How can you evaluate a DE model?', 'Compare predictions with data, check long-term behaviour, and assess assumptions.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the period of SHM x'''' = −ω²x?', '2π/ω.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How do you find the amplitude of x = 3 cos 2t + 4 sin 2t?', '√(9 + 16) = 5.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What does a negative coefficient in the auxiliary roots imply for long-term behaviour?', 'Solutions decay to zero (the system is stable).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What does a positive real root imply for long-term behaviour?', 'Solutions grow without limit (the system is unstable).', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is an electrical circuit modelled by a DE?', 'E.g. L d²q/dt² + R dq/dt + q/C = E(t), analogous to damped oscillation.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is a limitation of the logistic model?', 'It assumes a constant carrying capacity and growth rate.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'In a predator–prey model, what does x'' = ax − bxy represent?', 'Prey grow at rate a and are eaten at a rate proportional to encounters xy.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How do you interpret the constants in a model?', 'Relate each to a physical quantity or rate, e.g. k as a damping coefficient.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What does it mean if a model gives negative populations?', 'The model has broken down; it is only valid over a limited range.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How can initial conditions be used in modelling DEs?', 'They determine the constants and give the specific solution for the situation.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Further Mathematics' AND exam_board = 'Edexcel' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
